+    const int num_threads = 10;
+    const int n_threads = std::min(n, num_threads);
+    const int block_size = 32; // Tile size for loop tiling
+
+    // Optimized implementation using loop interchange (i-j-k) and NEON intrinsics
+    // We parallelize over the outer loop 'i' (rows of C/A)
+    std::vector<std::thread> threads;
+    
+    auto compute_block = [&](int start_i, int end_i) {
+        for (int i = start_i; i < end_i; ++i) {
+            // Initialize C[i, *] to zero implicitly by writing full result
+            // Inner loops use i-k-j order conceptually, but we implement i-j-k
+            // to leverage vectorization over j (columns of C)
+            for (int j = 0; j < n; ++j) {
+                float sum = 0.0f;
+                #ifdef __ARM_NEON
+                // Vectorized inner loop over k using NEON FMA
+                #define VEC_SIZE 4
+                for (int k = 0; k < n; k += VEC_SIZE) {
+                    // Load A[i, k..k+3]
+                    float4 a_vec = vld1q_f32(&A[i * n + k]);
+                    // Load B[k..k+3, j] (B is row-major, so B[k*n + j] is the element)
+                    // This requires loading elements one by one or transposing B,
+                    // but since we are sticking to the constraint of row-major B,
+                    // we load B[k*n + j] for k=k..k+3.
+                    float4 b_vec = {
+                        B[(k + 0) * n + j], 
+                        B[(k + 1) * n + j], 
+                        B[(k + 2) * n + j], 
+                        B[(k + 3) * n + j]
+                    };
+                    // Fused Multiply-Add: sum = sum + A * B
+                    sum += vmlaq_f32(sum, a_vec, b_vec);
+                }
+                // Handle remainder
+                for (int k = n - (n % VEC_SIZE); k < n; ++k) {
+                    sum += A[i * n + k] * B[k * n + j];
+                }
+                #else
+                // Standard scalar inner loop for non-NEON or fallback
+                for (int k = 0; k < n; ++k) {
+                    sum += A[i * n + k] * B[k * n + j];
+                }
+                #endif
+                C[i * n + j] = sum;
+            }
         }
+    };
+
+    // Simple distribution of rows to threads
+    int chunk_size = (n + n_threads - 1) / n_threads;
+    for (int t = 0; t < n_threads; ++t) {
+        int start_i = t * chunk_size;
+        int end_i = std::min(n, (t + 1) * chunk_size);
+        threads.emplace_back(compute_block, start_i, end_i);
+    }
+
+    for (auto& th : threads) th.join();
 }
